contacts = []
page_index = 0
while True:
    resp = apis.phone.search_contacts(access_token=phone_token, query='Denise', page_index=page_index, page_limit=20)
    print('page', page_index, 'resp', resp)
    if not resp:
        break
    if isinstance(resp, dict) and 'results' in resp:
        results = resp['results']
    else:
        results = resp
    # normalize list
    if not results:
        break
    contacts.extend(results)
    page_index += 1

print('total_matches', len(contacts))
for c in contacts:
    print(c.get('first_name'), c.get('last_name'), c.get('email'), c.get('phone_number'), c.get('contact_id'))

